// One neutral job shape, whatever the caller sends. This is the contract that
// replaces the dead Sora step: the calling workflow passes a prompt and a few
// options, and never has to know which provider ends up rendering it.
const j = $json || {};

function pick(keys, fallback) {
  for (const k of keys) {
    const v = j[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return fallback;
}

const prompt = String(pick(['prompt', 'text', 'description'], '')).trim();
if (prompt.length < 8) {
  throw new Error('A prompt of at least 8 characters is required. Received: ' + JSON.stringify(j.prompt));
}

// Clamp to what the providers actually accept, so a silly value fails here
// rather than after a paid call.
const duration = Math.max(4, Math.min(30, Number(pick(['durationSeconds', 'duration'], 10)) || 10));
const aspect = String(pick(['aspectRatio', 'aspect_ratio'], '16:9'));
const resolution = String(pick(['resolution'], '720p'));
const firstFrameUrl = String(pick(['firstFrameUrl', 'imageUrl', 'first_frame_url'], ''));
const callbackUrl = String(pick(['callbackUrl', 'callBackUrl'], ''));

// Default chain. Seedance leads because it does not require a callback URL.
// Add or reorder ids from the Kie.ai model list; an unknown id simply fails
// and the chain moves on, which is the whole point of having one.
const chain = String(pick(['modelChain'], 'bytedance/seedance-2,veo-3-1'))
  .split(',').map(function (s) { return s.trim(); }).filter(Boolean);

// A stable key over everything that changes the output, so an identical job is
// never paid for twice.
const seed = [prompt, duration, aspect, resolution, firstFrameUrl, chain.join('|')].join('::');
let hash = 0;
for (let i = 0; i < seed.length; i += 1) hash = ((hash << 5) - hash + seed.charCodeAt(i)) | 0;
const jobKey = 'job_' + Math.abs(hash).toString(36);

return [{
  json: {
    jobKey: jobKey,
    prompt: prompt,
    durationSeconds: duration,
    aspectRatio: aspect,
    resolution: resolution,
    firstFrameUrl: firstFrameUrl,
    callbackUrl: callbackUrl,
    modelChain: chain,
    requestedAt: new Date().toISOString(),
  },
}];

// Every provider on Kie.ai names its input fields differently, so the neutral
// job is translated once per model here. The chain becomes one item per
// attempt, tried in order until one of them returns a video.
const job = $('Normalize Job Request').first().json;

function inputFor(model) {
  const m = String(model).toLowerCase();

  if (m.indexOf('seedance') !== -1) {
    const input = {
      prompt: job.prompt,
      aspect_ratio: job.aspectRatio,
      duration: job.durationSeconds,
      resolution: job.resolution,
      generate_audio: true,
    };
    if (job.firstFrameUrl) input.first_frame_url = job.firstFrameUrl;
    return input;
  }

  if (m.indexOf('veo') !== -1) {
    const input = {
      prompt: job.prompt,
      aspect_ratio: job.aspectRatio === '1:1' ? 'auto' : job.aspectRatio,
      generation_type: job.firstFrameUrl ? 'FIRST_AND_LAST_FRAMES_2_VIDEO' : 'TEXT_2_VIDEO',
      enable_translation: true,
    };
    if (job.firstFrameUrl) input.image_urls = [job.firstFrameUrl];
    return input;
  }

  // Anything else gets the common fields and is allowed to fail into the next
  // model rather than stopping the run.
  const input = { prompt: job.prompt, aspect_ratio: job.aspectRatio, duration: job.durationSeconds };
  if (job.firstFrameUrl) input.first_frame_url = job.firstFrameUrl;
  return input;
}

return job.modelChain.map(function (model, i) {
  const body = { model: model, input: inputFor(model) };
  if (job.callbackUrl) body.callBackUrl = job.callbackUrl;
  return {
    json: {
      attempt: i + 1,
      model: model,
      requestBody: JSON.stringify(body),
      jobKey: job.jobKey,
    },
  };
});

// Kie.ai returns the file list as a JSON string inside resultJson, and reports
// cost in credits. Read both, and treat a poll that ran out of attempts as a
// failure of this model rather than a failure of the whole job.
const attempt = $('Loop Over Model Chain').item.json;
const body = $json || {};
const data = body.data || {};
const state = String(data.state || '').toLowerCase();

let videoUrl = '';
try {
  const parsed = data.resultJson ? JSON.parse(data.resultJson) : {};
  const urls = parsed.resultUrls || parsed.result_urls || [];
  videoUrl = Array.isArray(urls) && urls.length ? String(urls[0]) : '';
} catch (e) {
  videoUrl = '';
}

const settled = state === 'success' || state === 'fail';
let outcome = state;
let reason = data.failMsg || '';

if (!settled) {
  outcome = 'timed out';
  reason = 'The render was still ' + (state || 'queued') + ' when polling gave up.';
}
if (state === 'success' && !videoUrl) {
  outcome = 'fail';
  reason = 'The task reported success but returned no file URL.';
}

return [{
  json: {
    attempt: attempt.attempt,
    model: attempt.model,
    jobKey: attempt.jobKey,
    taskId: data.taskId || '',
    outcome: outcome,
    delivered: outcome === 'success' && !!videoUrl,
    videoUrl: videoUrl,
    failReason: reason,
    failCode: data.failCode || '',
    creditsConsumed: Number(data.creditsConsumed || 0),
    renderSeconds: Math.round(Number(data.costTime || 0) / 1000),
  },
}];

// Gather every attempt, whichever branch reached here, and report the one that
// worked along with what the failures cost. The caller gets a single, flat
// answer in both cases.
const attempts = $('Read Render Result').all().map(function (i) { return i.json; });
const job = $('Normalize Job Request').first().json;

const winner = attempts.find(function (a) { return a.delivered; }) || null;
const credits = attempts.reduce(function (s, a) { return s + (a.creditsConsumed || 0); }, 0);

const trail = attempts.map(function (a) {
  return a.model + ': ' + a.outcome + (a.failReason ? ' (' + a.failReason + ')' : '');
});

return [{
  json: {
    jobKey: job.jobKey,
    prompt: job.prompt,
    durationSeconds: job.durationSeconds,
    aspectRatio: job.aspectRatio,
    delivered: !!winner,
    model: winner ? winner.model : '',
    taskId: winner ? winner.taskId : '',
    videoUrl: winner ? winner.videoUrl : '',
    attemptsMade: attempts.length,
    modelsTried: attempts.map(function (a) { return a.model; }).join(', '),
    creditsConsumed: credits,
    renderSeconds: winner ? winner.renderSeconds : 0,
    attemptTrail: trail.join(' | '),
    finishedAt: new Date().toISOString(),
  },
}];
